const W: Record<string, Record<string, number>> = {
  lightSleeper: { noise: 0.55, roadworks: 0.2, airQuality: 0.1, realNights: 0.15, nightlife: 0 },
  nightOut: { noise: 0.3, roadworks: 0.1, airQuality: 0.05, realNights: 0.1, nightlife: 0.45 },
};
const names = ["Quayside Rooms","Grey Street Hotel","Central Station Inn","Jesmond Lodge","Ouseburn Loft","Toon Townhouse","Castle Garth Hotel","Haymarket Suites","Gateshead Riverside","Eldon Square Stay","Bigg Market Hotel","Leazes Park Inn","Heaton House","Tyne Bridge Hotel","Chinatown Guesthouse"];
const dir = "packages/shared/src/stays/fixtures/";
for (const profile of Object.keys(W)) {
  const hotels = names.map((name, i) => {
    const v: Record<string, number> = {
      noise: ((i * 37 + 20) % 80) + 15,
      roadworks: ((i * 53 + 10) % 70) + 30,
      airQuality: ((i * 29 + 40) % 45) + 50,
      realNights: i % 4 === 0 ? 50 : ((i * 11) % 60) + 30,
      nightlife: ((i * 61 + 5) % 85) + 10,
    };
    const breakdown: Record<string, unknown> = {};
    let total = 0;
    for (const k of Object.keys(v)) {
      const weight = W[profile][k];
      const points = Math.round(v[k] * weight * 10) / 10;
      total += points;
      breakdown[k] = { value: v[k], weight, points };
    }
    return {
      hotelId: `osm-node-${1000 + i}`,
      name,
      location: { lat: +(54.97 + (i % 5) * 0.004).toFixed(4), lng: +(-1.62 + (i % 3) * 0.006).toFixed(4) },
      pricePerNightGbp: 60 + ((i * 17) % 90),
      score: Math.round(total),
      breakdown,
      sources: {
        sensors: [{ id: `obs-${100 + i}`, distanceM: 80 + i * 20 }, { id: `obs-${200 + i}`, distanceM: 150 + i * 25 }],
        permits: i % 3 === 0 ? [{ ref: `SM-2026-${4000 + i}`, distanceM: 90 + i * 5, overlapsStay: true, nightWork: i % 2 === 0 }] : [],
        realNights: { count: i % 4 === 0 ? 0 : ((i * 3) % 9) + 3, simulated: true },
      },
      estimate: true,
      bookingUrl: `https://example.com/book/osm-node-${1000 + i}`,
      simulated: true,
    };
  }).sort((a, b) => b.score - a.score);
  const file = profile === "lightSleeper" ? "rank-light-sleeper.json" : "rank-night-out.json";
  await Bun.write(dir + file, JSON.stringify({ profile, checkIn: "2026-11-20", checkOut: "2026-11-22", hotels }, null, 2) + "\n");
}

